```typescript
// src/lib/eventBus.ts

type EventMap = {
  "user:login": { userId: string; timestamp: number };
  "user:logout": { userId: string; reason?: string };
  "order:created": { orderId: string; items: Array<{ sku: string; qty: number }> };
  "order:fulfilled": { orderId: string; fulfilledAt: Date };
  "analytics:track": { event: string; properties: Record<string, unknown> };
};

type EventKey = keyof EventMap;

type EventCallback<T extends EventKey> = (payload: EventMap[T]) => void;

class EventBus {
  private listeners: {
    [K in EventKey]?: Array<EventCallback<K>>;
  } = {};

  on<K extends EventKey>(event: K, callback: EventCallback<K>): () => void {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    (this.listeners[event] as Array<EventCallback<K>>).push(callback);

    return () => this.off(event, callback);
  }

  off<K extends EventKey>(event: K, callback: EventCallback<K>): void {
    const cbs = this.listeners[event];
    if (!cbs) return;
    this.listeners[event] = cbs.filter((cb) => cb !== callback) as any;
  }

  emit<K extends EventKey>(event: K, payload: EventMap[K]): void {
    const cbs = this.listeners[event];
    if (!cbs) return;
    for (const cb of cbs) {
      (cb as any)(payload);
    }
  }

  once<K extends EventKey>(event: K, callback: EventCallback<K>): () => void {
    const wrapper = ((payload: EventMap[K]) => {
      this.off(event, wrapper);
      callback(payload);
    }) as EventCallback<K>;
